    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    voter_token uuid,
    id uuid DEFAULT uuidv7() NOT NULL,
    CONSTRAINT review_votes_identity_chk CHECK ((((customer_id IS NOT NULL) AND (voter_token IS NULL)) OR ((customer_id IS NULL) AND (voter_token IS NOT NULL)))),
    CONSTRAINT review_votes_value_check CHECK ((value = ANY (ARRAY['-1'::integer, 1])))
);


