    channel_id uuid NOT NULL,
    locale text NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    is_verified_purchase boolean DEFAULT false NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    moderated_at timestamp with time zone,
    moderated_by uuid,
    moderator_note text DEFAULT ''::text NOT NULL,
    guest_name text DEFAULT ''::text NOT NULL,
    guest_email text DEFAULT ''::text NOT NULL,
    moderation_label text DEFAULT ''::text NOT NULL,
    moderation_reason text DEFAULT ''::text NOT NULL,
    moderation_checked_at timestamp with time zone,
    merchant_reply text DEFAULT ''::text NOT NULL,
    merchant_reply_at timestamp with time zone,
    merchant_reply_by uuid,
    moderation_tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    category_slugs jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT reviews_author_present_chk CHECK ((((customer_id IS NOT NULL) AND (guest_name = ''::text)) OR ((customer_id IS NULL) AND (guest_name <> ''::text)))),
    CONSTRAINT reviews_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


