--
-- Name: scheduled_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduled_jobs (
    id uuid DEFAULT uuidv7() NOT NULL,
    name text NOT NULL,
    kind text DEFAULT 'code'::text NOT NULL,
    schedule text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    next_run_at timestamp with time zone,
    locked_until timestamp with time zone,
    last_run_at timestamp with time zone,
    last_status text DEFAULT ''::text NOT NULL,
    last_error text DEFAULT ''::text NOT NULL,
    last_duration_ms integer,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    timezone text DEFAULT ''::text NOT NULL,
    max_attempts integer DEFAULT 1 NOT NULL,
    retry_backoff_seconds integer DEFAULT 60 NOT NULL,
    current_attempt integer DEFAULT 0 NOT NULL,
    alert_after_failures integer DEFAULT 0 NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    alerted boolean DEFAULT false NOT NULL,
    timeout_seconds integer DEFAULT 300 NOT NULL,
    CONSTRAINT scheduled_jobs_alert_after_failures_check CHECK ((alert_after_failures >= 0)),
    CONSTRAINT scheduled_jobs_kind_check CHECK ((kind = ANY (ARRAY['code'::text, 'webhook'::text]))),
    CONSTRAINT scheduled_jobs_last_status_check CHECK ((last_status = ANY (ARRAY[''::text, 'success'::text, 'error'::text]))),
    CONSTRAINT scheduled_jobs_max_attempts_check CHECK ((max_attempts >= 1)),
    CONSTRAINT scheduled_jobs_retry_backoff_seconds_check CHECK ((retry_backoff_seconds >= 0))
);


